class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")

        if len(self.rolls) >= 21:
            raise Exception("cannot roll after the game is complete")

        if self._in_tenth_frame():
            self._roll_tenth_frame(pins)
        else:
            self.rolls.append(pins)

    def score(self):
        if not self._is_complete():
            raise Exception("cannot score an incomplete game")

        total = 0
        for frame in range(10):
            start = self._frame_start(frame)
            first = self.rolls[start]
            second = self.rolls[start + 1] if start + 1 < len(self.rolls) else 0

            if first == 10:
                total += 10 + self.rolls[start + 1] + self.rolls[start + 2]
            elif first + second == 10:
                total += 10 + self.rolls[start + 2]
            else:
                total += first + second
        return total

    def _frame_start(self, frame):
        start = 0
        for roll in self.rolls[: frame * 2]:
            if roll == 10:
                start += 1
            else:
                start += 2
        return start

    def _in_tenth_frame(self):
        return self._frame_start(9) == len(self.rolls)

    def _roll_tenth_frame(self, pins):
        frame_rolls = self.rolls[self._frame_start(9):]
        if len(frame_rolls) == 0:
            self.rolls.append(pins)
        elif len(frame_rolls) == 1:
            if frame_rolls[0] == 10 and pins > 10:
                raise Exception("pins must be between 0 and 10")
            self.rolls.append(pins)
        elif len(frame_rolls) == 2:
            if frame_rolls[0] == 10 and pins > 10:
                raise Exception("pins must be between 0 and 10")
            if frame_rolls[0] != 10 and frame_rolls[0] + frame_rolls[1] == 10 and pins > 10:
                raise Exception("pins must be between 0 and 10")
            self.rolls.append(pins)

    def _is_complete(self):
        if len(self.rolls) == 0:
            return False
        tenth = self.rolls[self._frame_start(9):]
        if len(tenth) < 2:
            return False
        if tenth[0] == 10:
            return len(tenth) == 3
        if tenth[0] + tenth[1] == 10:
            return len(tenth) == 3
        return len(tenth) == 2

