class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("pins must be between 0 and 10")

        if self._is_complete():
            raise Exception("cannot roll after the game is complete")

        if self._in_tenth_frame():
            self._roll_tenth_frame(pins)
        else:
            frames = self._frames()
            if len(frames[-1]) == 1 and pins > 10 - frames[-1][0]:
                raise Exception("cannot knock down more pins than are standing")
            self.rolls.append(pins)

    def score(self):
        if not self._is_complete():
            raise Exception("cannot score an incomplete game")

        total = 0
        start = 0
        for _ in range(9):
            first = self.rolls[start]
            if first == 10:
                total += 10 + self.rolls[start + 1] + self.rolls[start + 2]
                start += 1
            else:
                second = self.rolls[start + 1]
                if first + second == 10:
                    total += 10 + self.rolls[start + 2]
                else:
                    total += first + second
                start += 2
        total += sum(self.rolls[start:])
        return total

    def _frames(self):
        frames = []
        i = 0
        while i < len(self.rolls):
            if self.rolls[i] == 10:
                frames.append([self.rolls[i]])
                i += 1
            else:
                frames.append(self.rolls[i:i + 2])
                i += 2
        return frames

    def _is_complete(self):
        if not self.rolls:
            return False
        frames = self._frames()
        if len(frames) < 10 or not self._frames_complete(frames[:9]):
            return False
        tenth = self.rolls[self._tenth_start():]
        if tenth[0] == 10:
            return len(tenth) == 3
        if tenth[0] + tenth[1] == 10:
            return len(tenth) == 3
        return len(tenth) == 2

    @staticmethod
    def _frames_complete(frames):
        return all(len(f) == 2 or f == [10] for f in frames)

    def _in_tenth_frame(self):
        frames = self._frames()
        return len(frames) >= 9 and self._frames_complete(frames[:9])

    def _tenth_start(self):
        frames = self._frames()
        return sum(len(f) for f in frames[:9])

    def _roll_tenth_frame(self, pins):
        tenth = self.rolls[self._tenth_start():]
        if len(tenth) == 1:
            if tenth[0] != 10 and pins > 10 - tenth[0]:
                raise Exception("cannot knock down more pins than are standing")
        elif len(tenth) == 2:
            if pins > 10 - tenth[1]:
                raise Exception("cannot knock down more pins than are standing")
        self.rolls.append(pins)

